\draw[bluearr, -, opacity=0.85] (e5.east) -- (12.80, -2.5);
\draw[bluearr, -, opacity=0.85] (12.80, -1.2) -- (12.80, -2.5);
\draw[bluearr, opacity=0.85] (12.80, -1.2) -- (sum.south);
